// reactstrap components
import {
    Button,
    Card,
    CardHeader,
    CardBody,
    FormGroup,
    Form,
    Input,
    Container,
    Row,
    Col,
    Label,
  } from "reactstrap";
  import { useState } from "react";
  import AIHelper from "components/AIHelper"; // Placeholder for AI suggestions

  const CarbonDataInput = () => {
    const [carbonData, setCarbonData] = useState({
      date: "",
      category: "",
      value: "",
      unit: "",
    });
    const [submitted, setSubmitted] = useState(false);

    const handleChange = (e) => {
      setCarbonData({ ...carbonData, [e.target.name]: e.target.value });
    };

    const handleSubmit = (e) => {
      e.preventDefault();
      setSubmitted(true);
      setTimeout(() => setSubmitted(false), 2000); // Reset UI after saving
    };

    const getValidUnits = (category) => {
      switch (category) {
        case "Transport":
          return ["kg", "liters"];
        case "Electricity":
          return ["kWh"];
        case "Diet":
          return ["kg"];
        case "Waste":
          return ["kg"];
        default:
          return [];
      }
    };

    return (
      <Container className="mt-5" fluid>
        <Row className="justify-content-center">
          <Col lg="8">
            <Card className="bg-secondary shadow">
              <CardHeader className="bg-white border-0 text-center">
                <h3 className="mb-0">Carbon Data Input</h3>
              </CardHeader>
              <CardBody>
                <Form onSubmit={handleSubmit}>
                  <Row>
                    <Col md="6">
                      <FormGroup>
                        <Label>Date</Label>
                        <Input
                          type="date"
                          name="date"
                          value={carbonData.date}
                          onChange={handleChange}
                        />
                      </FormGroup>
                    </Col>
                  </Row>
                  <Row>
                    <Col md="6">
                      <FormGroup>
                        <Label>Activity Category</Label>
                        <Input
                          type="select"
                          name="category"
                          value={carbonData.category}
                          onChange={handleChange}
                        >
                          <option value="">Select Category</option>
                          <option value="Transport">Transport</option>
                          <option value="Electricity">Electricity</option>
                          <option value="Diet">Diet</option>
                          <option value="Waste">Waste Management</option>
                        </Input>
                      </FormGroup>
                    </Col>
                    <Col md="6">
                      <FormGroup>
                        <Label>Value</Label>
                        <Input
                          type="number"
                          name="value"
                          placeholder="Enter amount"
                          value={carbonData.value}
                          onChange={handleChange}
                        />
                      </FormGroup>
                    </Col>
                  </Row>
                  <Row>
                    <Col md="6">
                      <FormGroup>
                        <Label>Unit</Label>
                        <Input
                          type="select"
                          name="unit"
                          value={carbonData.unit}
                          onChange={handleChange}
                          disabled={!carbonData.category} // Disable until category is selected
                        >
                          <option value="">Select Unit</option>
                          {getValidUnits(carbonData.category).map((unit) => (
                            <option key={unit} value={unit}>{unit}</option>
                          ))}
                        </Input>
                      </FormGroup>
                    </Col>
                  </Row>
                  <Row className="text-center">
                    <Col>
                      <Button color="primary" type="submit">
                        Save Data
                      </Button>
                    </Col>
                  </Row>
                </Form>
                <div className="mt-4 text-center">
                  <AIHelper category={carbonData.category} value={carbonData.value} />
                </div>
              </CardBody>
            </Card>
          </Col>
        </Row>
      </Container>
    );
  };

  export default CarbonDataInput;
